// Utilisé seulement si la table de prix n'a pas pu être lue dans la page.
const PRIX_SECOURS = { "Court (TikTok / Reels)": 45, "Long (YouTube / Best-of)": 125, "Business / Sponsorisé": 300 };

const b64 = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));

export async function onRequest({ request, next }) {
  const path = new URL(request.url).pathname.replace(/\/+$/, "").toLowerCase() || "/";

  // Images de partage.
  const og = path.match(/^\/og\/([a-z0-9-]+)\.jpg$/);
  if (og && OG_DATA[og[1]] && (request.method === "GET" || request.method === "HEAD")) {
    return new Response(request.method === "HEAD" ? null : b64(OG_DATA[og[1]]), {
      headers: { "content-type": "image/jpeg", "cache-control": "public, max-age=31536000, immutable" },
    });
  }

  const res = await next();
  if (request.method !== "GET" || !(res.headers.get("content-type") || "").includes("text/html")) return res;

  const meta = ROUTES[path];

  // Chemin inconnu (hors accueil) : vraie réponse 404, la page affiche son écran « introuvable ».
  if (!meta) {
    if (path === "/" || path === "/index.html" || path.startsWith("/api/")) return res;
    return new Response(res.body, { status: 404, headers: res.headers });
  }

  // Table de prix : le script prices-src précède <title> et les <meta>, elle est donc lue avant eux.
  let prix = PRIX_SECOURS, src = "";
  const fmt = (s) => s.replace(/\{P:([^}]+)\}/g, (m, k) => (prix[k] != null ? prix[k] + " €" : ""));

  const [t0, d0, ogImage] = meta;
  const url = SITE + path;
  const attr = (name, value) => ({ element: (e) => e.setAttribute(name, fmt(value)) });
  const rw = new HTMLRewriter()
    .on("script#prices-src", {
      text(chunk) {
        src += chunk.text;
        if (!chunk.lastInTextNode) return;
        try {
          const m = src.match(/window\.MICHYY_PRICES\s*=\s*(\{[\s\S]*?\n\});/);
          const f = m && JSON.parse(m[1]).formats;
          if (f) prix = f;
        } catch (e) {}
      },
    })
    .on("title", { element: (e) => e.setInnerContent(fmt(t0)) })
    .on('meta[name="description"]', attr("content", d0))
    .on('meta[property="og:title"]', attr("content", t0))
    .on('meta[property="og:description"]', attr("content", d0))
    .on('meta[property="og:url"]', attr("content", url))
    .on('meta[name="twitter:title"]', attr("content", t0))
    .on('meta[name="twitter:description"]', attr("content", d0))
    .on('link[rel="canonical"]', attr("href", url));
  if (ogImage) {
    const img = SITE + "/og/" + ogImage + ".jpg?v=" + OG_V;
    rw.on('meta[property="og:image"]', attr("content", img))
      .on('meta[property="og:image:secure_url"]', attr("content", img))
      .on('meta[property="og:image:alt"]', attr("content", t0))
      .on('meta[name="twitter:image"]', attr("content", img))
      .on('meta[name="twitter:image:alt"]', attr("content", t0));
  }
  return rw.transform(res);
}

